	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/disputes/{id}", wrapper.GetAdminDispute)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/disputes/{id}/actions", wrapper.ActOnAdminDispute)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/markets", wrapper.ListAdminMarkets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/markets/{id}", wrapper.GetAdminMarket)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/markets/{id}/actions", wrapper.ActOnAdminMarket)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/mm-applications", wrapper.ListMmApplications)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/mm-applications/{id}/actions", wrapper.DecideMmApplication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/overview", wrapper.GetAdminOverview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users", wrapper.ListAdminUsers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users/{id}", wrapper.GetAdminUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/users/{id}/actions", wrapper.ActOnAdminUser)
